// An in-memory task store.
export function createStore() {
  const tasks = [];
  let nextId = 1;
  return {
    add(title, { tags = [] } = {}) {
      const normalized = [];
      for (const raw of tags) {
        if (typeof raw !== 'string') continue;
        const tag = raw.trim().toLowerCase();
        if (tag && !normalized.includes(tag)) normalized.push(tag);
      }
      const task = { id: nextId++, title, done: false, tags: normalized };
      tasks.push(task);
      return { ...task, tags: [...task.tags] };
    },
    complete(id) {
      const task = tasks.find((item) => item.id === id);
      if (!task) throw new Error('No task ' + id);
      task.done = true;
      return { ...task, tags: [...task.tags] };
    },
    list({ tag } = {}) {
      let result = tasks;
      if (tag !== undefined) {
        const wanted = String(tag).trim().toLowerCase();
        result = tasks.filter((task) => task.tags.includes(wanted));
      }
      return result.map((task) => ({ ...task, tags: [...task.tags] }));
    },
  };
}

export function formatTask(task) {
  const base = (task.done ? '[x]' : '[ ]') + ' ' + task.id + ' ' + task.title;
  const tags = Array.isArray(task.tags) ? task.tags : [];
  return base + tags.map((tag) => ' #' + tag).join('');
}

import { formatTask } from './format.js';

// Splits arguments into positional words, collected tags and the remaining
// options. Unknown options are rejected.
function parseArgs(args) {
  const positional = [];
  const tags = [];
  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg === '--tag') {
      const value = args[i + 1];
      if (value === undefined || value.startsWith('--')) {
        throw new Error('--tag needs a value');
      }
      tags.push(value);
      i += 1;
    } else if (arg.startsWith('--')) {
      throw new Error('Unknown option: ' + arg);
    } else {
      positional.push(arg);
    }
  }
  return { positional, tags };
}

// Runs one command and returns the lines to print.
export function run(store, argv) {
  const [command, ...rest] = argv;
  if (command === 'add') {
    const { positional, tags } = parseArgs(rest);
    return [formatTask(store.add(positional.join(' '), { tags }))];
  }
  if (command === 'done') {
    const { positional } = parseArgs(rest);
    return [formatTask(store.complete(Number(positional[0])))];
  }
  if (command === 'list') {
    const { tags } = parseArgs(rest);
    const options = tags.length > 0 ? { tag: tags[0] } : {};
    return store.list(options).map(formatTask);
  }
  throw new Error('Unknown command: ' + command);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { createStore } from '../src/store.js';

test('add and complete', () => {
  const store = createStore();
  const task = store.add('Buy milk');
  assert.equal(store.complete(task.id).done, true);
});

test('add without tags gives an empty tags array', () => {
  const store = createStore();
  assert.deepEqual(store.add('Buy milk').tags, []);
  assert.deepEqual(store.list()[0].tags, []);
});

test('add trims and lower-cases tags and drops duplicates', () => {
  const store = createStore();
  const task = store.add('Buy milk', { tags: [' Home ', 'home', 'ERRAND', '  ', 'errand'] });
  assert.deepEqual(task.tags, ['home', 'errand']);
  assert.deepEqual(store.list()[0].tags, ['home', 'errand']);
});

test('every task has a tags array', () => {
  const store = createStore();
  store.add('A');
  store.add('B', { tags: ['x'] });
  for (const task of store.list()) assert.ok(Array.isArray(task.tags));
});

test('list with a tag filters case-insensitively', () => {
  const store = createStore();
  store.add('Buy milk', { tags: ['home'] });
  store.add('Ship parcel', { tags: ['errand', 'home'] });
  store.add('Read book');

  assert.deepEqual(store.list({ tag: 'home' }).map((t) => t.title), ['Buy milk', 'Ship parcel']);
  assert.deepEqual(store.list({ tag: 'HOME' }).map((t) => t.title), ['Buy milk', 'Ship parcel']);
  assert.deepEqual(store.list({ tag: 'missing' }), []);
});

test('list without a tag returns every task', () => {
  const store = createStore();
  store.add('One', { tags: ['a'] });
  store.add('Two');
  assert.deepEqual(store.list().map((t) => t.title), ['One', 'Two']);
});

test('returned tasks do not share their tags array with the store', () => {
  const store = createStore();
  const task = store.add('Buy milk', { tags: ['home'] });
  task.tags.push('mutated');
  assert.deepEqual(store.list()[0].tags, ['home']);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { formatTask } from '../src/format.js';

test('formats an open task without tags as before', () => {
  assert.equal(formatTask({ id: 1, title: 'Buy milk', done: false, tags: [] }), '[ ] 1 Buy milk');
  assert.equal(formatTask({ id: 2, title: 'Old task', done: false }), '[ ] 2 Old task');
});

test('formats a done task without tags as before', () => {
  assert.equal(formatTask({ id: 1, title: 'Buy milk', done: true, tags: [] }), '[x] 1 Buy milk');
});

test('appends tags after the title', () => {
  assert.equal(
    formatTask({ id: 1, title: 'Buy milk', done: false, tags: ['home', 'errand'] }),
    '[ ] 1 Buy milk #home #errand',
  );
  assert.equal(
    formatTask({ id: 3, title: 'Done thing', done: true, tags: ['work'] }),
    '[x] 3 Done thing #work',
  );
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { run } from '../src/cli.js';
import { createStore } from '../src/store.js';

test('add with repeated tags prints the formatted task', () => {
  const store = createStore();
  assert.deepEqual(run(store, ['add', 'Buy', 'milk', '--tag', 'home', '--tag', 'errand']), [
    '[ ] 1 Buy milk #home #errand',
  ]);
});

test('add without tags prints as before', () => {
  const store = createStore();
  assert.deepEqual(run(store, ['add', 'Buy', 'milk']), ['[ ] 1 Buy milk']);
});

test('list with a tag shows only that tag', () => {
  const store = createStore();
  run(store, ['add', 'Buy', 'milk', '--tag', 'home']);
  run(store, ['add', 'Ship', 'parcel', '--tag', 'errand']);
  assert.deepEqual(run(store, ['list', '--tag', 'HOME']), ['[ ] 1 Buy milk #home']);
});

test('list without a tag shows every task', () => {
  const store = createStore();
  run(store, ['add', 'One', '--tag', 'a']);
  run(store, ['add', 'Two']);
  assert.deepEqual(run(store, ['list']), ['[ ] 1 One #a', '[ ] 2 Two']);
});

test('an unknown option throws the expected message', () => {
  const store = createStore();
  assert.throws(() => run(store, ['add', 'Buy', 'milk', '--x']), {
    message: 'Unknown option: --x',
  });
});

test('a tag option with no value throws the expected message', () => {
  const store = createStore();
  assert.throws(() => run(store, ['add', 'Buy', 'milk', '--tag']), {
    message: '--tag needs a value',
  });
});
